<script setup>
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue';
import { Store } from '../../store';
import { lineTotal, money, cartItem, checkoutTotalsFor, createSale, isPaid, cents } from '../../domain/pos';
import { categoryPath, inventoryFacets, filterInventoryProducts } from '../../domain/inventoryCsv';
import { localPos } from '../../services/posLocal';
import { safeDraft, localReceiptPresentation, needsReceiptReview } from '../../domain/offlinePolicy';
import Icon from '../ui/EditionIcon.vue';
import Modal from '../ui/EditionModal.vue';
import Receipt from './pos/EditionReceipt.vue';
const failedImages = ref({});
// Each browser tab owns a cart; different tills still share the durable receipt outbox.
let registerId;
try { registerId=sessionStorage.getItem('myfin-register'); if(!registerId){registerId=crypto.randomUUID();sessionStorage.setItem('myfin-register',registerId);} } catch { registerId='default'; }
const uid=Store.state.currentUser.uid,companyId=Store.state.selectedCompany.id,draftKey=`${uid}:${companyId}:${registerId}`;
const newId=()=>crypto.randomUUID().replaceAll('-','').slice(0,20);
const cart=ref([]),held=ref([]),customerId=ref(''),saleId=ref(newId()),ready=ref(false),storageError=ref('');
const search=ref(''),category=ref('All items'),subcategory=ref('All'),modal=ref(''),variantProduct=ref(null),holdName=ref(''),busy=ref(false),error=ref(''),lastSale=ref(null),receipt=ref(null);
const customerEmail=ref(''),customerName=ref(''),discount=ref(0),overrideReason=ref('');
const selectedCustomer=computed(()=>clients.value.find(c=>c.id===customerId.value));
watch(customerId,()=>{customerEmail.value=selectedCustomer.value?.email||'';customerName.value=selectedCustomer.value?.name||'';});
const method=ref('Cash'),received=ref(''),confirmed=ref(false),productSearch=ref(null),cartPanel=ref(null);
const company=computed(()=>Store.state.selectedCompany||{}),currency=computed(()=>company.value.preferences?.currency||'RM');
const staffDiscountLimit=computed(()=>Math.min(100,Math.max(0,Number(company.value.preferences?.staffDiscountLimit||0))));
const discountLimit=computed(()=>Store.permissions().staff?staffDiscountLimit.value:100);
const reasonRequired=computed(()=>Store.permissions().manager&&Number(discount.value)>staffDiscountLimit.value);
const products=computed(()=>Store.state.products),clients=computed(()=>Store.state.clients.filter(c=>c.type!=='Supplier'));
const categories=computed(()=>['All items',...inventoryFacets(products.value).categories]);
const subcategories=computed(()=>category.value==='All items'?[]:['All',...inventoryFacets(products.value,category.value).subcategories]);
watch(category,()=>{subcategory.value='All';});
const filtered=computed(()=>filterInventoryProducts(products.value,{query:search.value,category:category.value==='All items'?'':category.value,subcategory:subcategory.value==='All'?'':subcategory.value}));
const productGroups=computed(()=>{const groups=new Map();for(const product of filtered.value){const [top,child]=categoryPath(product),label=category.value==='All items'?top:(child||'Other items');if(!groups.has(label))groups.set(label,[]);groups.get(label).push(product);}return [...groups].map(([label,items])=>({label,items}));});
const productPath=product=>categoryPath(product).join(' / ');
const totals=computed(()=>{try{return checkoutTotalsFor(cart.value,company.value.preferences?.taxRate??company.value.preferences?.tax??0,discount.value)}catch{return {subtotal:0,discountAmount:0,tax:0,totalBeforeRounding:0,rounding:0,total:0,taxRate:0,discount:0}}});
const count=computed(()=>cart.value.reduce((s,i)=>s+Number(i.qty),0));
const change=computed(()=>{const value=cents(received.value||0)-cents(totals.value.total);return Number.isFinite(value)?Math.max(0,value)/100:0;});
const roundingMoney=value=>{const amount=Number(value)||0;return `${amount>0?'+ ':amount<0?'− ':''}${money(Math.abs(amount),currency.value)}`;};
const recent=computed(()=>{const map=new Map();[...Store.state.transactions.filter(t=>isPaid(t)&&t.source==='pos'&&(!Store.permissions().staff||t.cashierId===uid)),...Store.state.pendingSales.map(s=>({...s,syncStatus:'pending'}))].forEach(s=>map.set(s.id,s));return [...map.values()].sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,30);});
function draft(){return {cart:cart.value,held:held.value,customerId:customerId.value,customerEmail:customerEmail.value,customerName:customerName.value,saleId:saleId.value,discount:discount.value,overrideReason:overrideReason.value};}
async function persist(){if(!ready.value||busy.value)return;try{await localPos.saveDraft(draftKey,draft());storageError.value='';}catch{storageError.value='This device could not save the order. Enable browser storage or free some space before taking payment.';}}
watch([cart,held,customerId,customerEmail,customerName,saleId,discount,overrideReason],persist,{deep:true});
onMounted(async()=>{try{const saved=await localPos.getDraft(draftKey);if(saved){cart.value=saved.cart||[];held.value=saved.held||[];customerId.value=saved.customerId||'';await Promise.resolve();customerEmail.value=saved.customerEmail||selectedCustomer.value?.email||'';customerName.value=saved.customerName||selectedCustomer.value?.name||'';saleId.value=saved.saleId||newId();discount.value=Number(saved.discount||0);overrideReason.value=saved.overrideReason||'';}await localPos.saveDraft(draftKey,draft());ready.value=true;}catch{storageError.value='Device storage is unavailable. Enable browser storage to use checkout.';}window.addEventListener('keydown',shortcut);});
onBeforeUnmount(()=>window.removeEventListener('keydown',shortcut));
function available(product,variant){const pending=Store.state.pendingSales.reduce((s,t)=>s+t.items.filter(i=>i.productId===product.id&&i.variantId===(variant?.id||'')).reduce((n,i)=>n+Number(i.qty),0),0);return (variant?.stock??product.stock)-pending;}
function quantityInCart(product,variant){return cart.value.filter(i=>i.productId===product.id&&i.variantId===(variant?.id||'')).reduce((s,i)=>s+Number(i.qty),0);}
function add(product,variant){if(!ready.value||busy.value)return;if(product.variants.length&&!variant){variantProduct.value=product;modal.value='variant';return;}if(product.trackStock&&quantityInCart(product,variant)+1>available(product,variant)){Store.notify('No more stock available for this item.','error');return;}const item=safeDraft(cartItem(product,variant));const existing=cart.value.find(i=>i.productId===item.productId&&i.variantId===item.variantId);if(existing)existing.qty++;else cart.value.push(item);modal.value='';}
function updateQty(index,value){const item=cart.value[index],q=Number(value),product=products.value.find(p=>p.id===item.productId),variant=product?.variants.find(v=>v.id===item.variantId);if(!Number.isFinite(q)||q<=0){cart.value.splice(index,1);return;}if(product?.trackStock&&q>available(product,variant)){Store.notify('That quantity exceeds available stock.','error');return;}item.qty=Math.round(q*1000)/1000;}
function openPayment(){error.value='';if(!Store.can('checkout'))return;if(!Number.isFinite(Number(discount.value))||Number(discount.value)>discountLimit.value||Number(discount.value)<0)return Store.notify('This discount exceeds your account policy. Review the order before taking payment.','error');if(reasonRequired.value&&overrideReason.value.trim().length<3)return Store.notify('Enter a reason of at least 3 characters for the manager discount.','error');if(!ready.value||storageError.value||!cart.value.length)return;for(const item of cart.value){const p=products.value.find(p=>p.id===item.productId),v=p?.variants.find(v=>v.id===item.variantId);if(!p||(item.variantId&&!v))return Store.notify(`${item.desc} is no longer available. Remove it and choose a current item.`,'error');if(Store.permissions().staff&&Number(item.price)!==Number(v?.price??p.price)){item.price=Number(v?.price??p.price);return Store.notify('The catalog price changed. Review the updated order before taking payment.','warning');}if(p.trackStock&&item.qty>available(p,v))return Store.notify(`${item.desc}: review available stock before payment.`,'error');}method.value='Cash';received.value='';confirmed.value=false;modal.value='payment';}
async function complete(){if(busy.value)return;error.value='';try{const sale=createSale({id:saleId.value,items:cart.value,company:company.value,user:Store.state.currentUser,method:method.value,received:received.value,confirmed:confirmed.value,customer:{...(selectedCustomer.value||clients.value.find(c=>c.email?.toLowerCase()===customerEmail.value.trim().toLowerCase()&&customerEmail.value.trim())||{}),name:customerName.value.trim()||selectedCustomer.value?.name||'',email:customerEmail.value.trim()},offline:!Store.state.online||Store.state.fromCache,discount:Number(discount.value),overrideReason:overrideReason.value});busy.value=true;const next={cart:[],held:held.value,customerId:'',saleId:newId()};const saved=await Store.completeSale(localReceiptPresentation(sale,company.value),draftKey,next);lastSale.value=saved;cart.value=[];customerId.value='';customerEmail.value='';customerName.value='';saleId.value=next.saleId;discount.value=0;overrideReason.value='';modal.value='success';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function hold(){held.value.push({id:newId(),name:holdName.value.trim()||`Order ${held.value.length+1}`,items:JSON.parse(JSON.stringify(cart.value)),customerId:customerId.value,customerEmail:customerEmail.value,customerName:customerName.value,saleId:saleId.value,discount:discount.value,overrideReason:overrideReason.value,total:totals.value.total,date:new Date().toISOString()});cart.value=[];customerId.value='';customerEmail.value='';customerName.value='';saleId.value=newId();discount.value=0;overrideReason.value='';modal.value='';await persist();Store.notify('Order held on this device.');}
async function restore(index){const order=held.value[index];if(cart.value.length)held.value.push({id:newId(),name:'Previous cart',items:JSON.parse(JSON.stringify(cart.value)),customerId:customerId.value,customerEmail:customerEmail.value,customerName:customerName.value,saleId:saleId.value,discount:discount.value,overrideReason:overrideReason.value,total:totals.value.total,date:new Date().toISOString()});cart.value=order.items;customerId.value=order.customerId;await Promise.resolve();customerEmail.value=order.customerEmail||selectedCustomer.value?.email||'';customerName.value=order.customerName||selectedCustomer.value?.name||'';saleId.value=order.saleId;discount.value=Number(order.discount||0);overrideReason.value=order.overrideReason||'';held.value.splice(index,1);modal.value='';}
function scan(){const code=search.value.trim().toUpperCase();if(!code)return;const matches=[];for(const p of products.value){if([p.sku,p.barcode,p.code].some(v=>v&&v.toUpperCase()===code))matches.push([p,null]);for(const v of p.variants)if([v.sku,v.barcode].some(c=>c&&c.toUpperCase()===code))matches.push([p,v]);}if(matches.length===1){add(...matches[0]);search.value='';}else Store.notify(matches.length?'Multiple items use this code. Choose the correct item.':'No exact SKU or barcode match.','error');}
function shortcut(e){if(modal.value||receipt.value)return;if(e.key==='F2'){e.preventDefault();productSearch.value?.focus();}if(e.key==='F8'){e.preventDefault();openPayment();}}
function viewCart(){cartPanel.value?.scrollIntoView({behavior:Store.state.preferences.reduceMotion?'instant':'smooth',block:'start'});}
</script>
<template><div class="ed-page ed-pos-page"><header class="ed-page-head"><div><div class="ed-eyebrow">POINT OF SALE / {{ company.name }}</div><h1>Make someone's day.</h1><p>A good checkout should feel effortless.</p></div><div class="ed-actions"><button class="ed-btn" @click="modal='held'"><Icon name="clock" />Held orders<span v-if="held.length" class="ed-pill">{{ held.length }}</span></button><button class="ed-btn" @click="modal='recent'"><Icon name="receipt" />Recent sales</button></div></header>
<div v-if="storageError" class="ed-notice error" role="alert">{{ storageError }}</div><div v-if="!Store.state.online||Store.state.fromCache" class="ed-notice warning"><Icon name="cloud" /><div><strong>Working offline</strong>Orders and receipts save on this device and sync after reconnecting. Other tills may have sold stock since your last connection. Access changes take effect after reconnecting. Confirm QR/card payments using the merchant device's own connection.</div></div>
<div class="ed-pos-layout"><section>
  <div class="ed-search" style="margin-bottom:15px"><Icon name="search" /><input ref="productSearch" v-model="search" class="ed-input" aria-label="Search products" placeholder="Search or scan SKU / barcode · Enter to add" @keydown.enter.prevent="scan"></div>
  <div class="ed-tabs" aria-label="Product categories"><button v-for="c in categories" :key="c" :class="{active:category===c}" :aria-pressed="category===c" @click="category=c">{{ c }}</button></div>
  <div v-if="subcategories.length>1" class="ed-tabs mf-pos-subcategories" :aria-label="`${category} subcategories`"><span>Choose a section</span><button v-for="child in subcategories" :key="child" :class="{active:subcategory===child}" :aria-pressed="subcategory===child" @click="subcategory=child">{{ child }}</button></div>
  <div v-if="filtered.length" class="mf-pos-groups">
    <section v-for="group in productGroups" :key="group.label" class="mf-pos-group">
      <header class="mf-pos-group-head"><div><span>{{ category==='All items'?'Category':'Section' }}</span><h2>{{ group.label }}</h2></div><small>{{ group.items.length }} {{ group.items.length===1?'item':'items' }}</small></header>
      <div class="ed-product-grid"><button v-for="p in group.items" :key="p.id" class="ed-product" :aria-label="`Add ${p.name}`" :disabled="!ready||busy||(p.trackStock&&(p.variants.length?p.variants.every(v=>available(p,v)<=0):available(p)<=0))" @click="add(p)"><img v-if="p.imageUrl && Store.state.online && !failedImages[p.imageUrl]" :src="p.imageUrl" @error="failedImages[p.imageUrl]=true" class="ed-product-thumb" alt="" loading="lazy"><span v-else class="ed-product-symbol"><Icon :name="p.category==='Service'?'clock':'box'" /></span><span v-if="p.trackStock&&!p.variants.length&&available(p)<5" class="ed-stock-label">{{ Math.max(0,available(p)) }} left</span><div><span class="mf-pos-product-path">{{ productPath(p) }}</span><strong>{{ p.name }}</strong><small>{{ p.variants.length?`${p.variants.length} options`:p.sku||'No SKU' }} · {{ p.unit }}</small></div><div class="ed-product-footer"><span>{{ p.variants.length?'From ':'' }}{{ money(p.variants.length?Math.min(...p.variants.map(v=>v.price)):p.price,currency) }}</span><Icon name="plus" /></div></button></div>
    </section>
  </div>
  <div v-else class="ed-empty"><Icon name="box" /><h3>{{ products.length?'No matching products':'Your catalog is ready to begin' }}</h3><p>{{ products.length?'Try another name, SKU, category, or section.':Store.can('inventoryWrite')?'Add products and stock to start taking orders.':'Ask a manager to prepare the product catalog.' }}</p><router-link v-if="!products.length" to="/products" class="ed-link">Open inventory<Icon name="arrow" /></router-link></div>
</section>
<aside ref="cartPanel" class="ed-cart"><div class="ed-cart-header"><div><h2>Current order</h2><small>{{ count }} {{ count===1?'item':'items' }} · Saved on this device</small></div><Icon name="bag" /></div><label class="ed-field"><span class="ed-eyebrow">Customer</span><select v-model="customerId" :disabled="busy"><option value="">Walk-in customer</option><option v-for="c in clients" :key="c.id" :value="c.id">{{ c.name }}{{ c.email?' · '+c.email:'' }}</option></select></label><div v-for="(item,i) in cart" :key="item.productId+item.variantId" class="ed-cart-item"><div style="display:flex;justify-content:space-between;gap:10px"><div><strong>{{ item.desc }}</strong><small>{{ money(item.price,currency) }} / {{ item.unit }}</small></div><button class="ed-icon-button" :aria-label="`Remove ${item.desc}`" :disabled="busy" @click="cart.splice(i,1)"><Icon name="close" /></button></div><div class="ed-cart-item-bottom"><div class="ed-quantity"><button :disabled="busy" :aria-label="`Decrease ${item.desc} quantity`" @click="updateQty(i,Number(item.qty)-1)"><Icon name="minus" /></button><input :value="item.qty" type="number" min="0.001" step="0.001" :aria-label="`${item.desc} quantity`" :disabled="busy" @change="updateQty(i,$event.target.value)"><button :disabled="busy" :aria-label="`Increase ${item.desc} quantity`" @click="updateQty(i,Number(item.qty)+1)"><Icon name="plus" /></button></div><span>{{ money(lineTotal(item),currency) }}</span></div></div><div v-if="!cart.length" class="ed-empty" style="border:0"><Icon name="bag" /><h3>A fresh order.</h3><p>Choose an item to get started.</p></div><div style="padding-top:12px"><label v-if="discountLimit>0||discount>0" class="ed-field"><span>Discount (%)</span><input v-model.number="discount" type="number" min="0" :max="discountLimit" step="0.01" :disabled="busy"><small>Account limit: {{ discountLimit }}%</small></label><label v-if="reasonRequired" class="ed-field"><span>Manager override reason *</span><input v-model.trim="overrideReason" maxlength="500" :disabled="busy" required placeholder="Why this discount is approved"></label><div class="ed-summary"><span>Subtotal</span><span>{{ money(totals.subtotal,currency) }}</span></div><div v-if="totals.discountAmount" class="ed-summary"><span>Discount {{ discount }}%</span><span>−{{ money(totals.discountAmount,currency) }}</span></div><div class="ed-summary"><span>Tax {{ totals.taxRate||0 }}%</span><span>{{ money(totals.tax,currency) }}</span></div><div class="ed-summary"><span>Total before rounding</span><span>{{ money(totals.totalBeforeRounding,currency) }}</span></div><div class="ed-summary"><span>Rounding</span><span>{{ roundingMoney(totals.rounding) }}</span></div><div class="ed-summary total"><span>Total</span><span>{{ money(totals.total,currency) }}</span></div></div><button class="ed-btn primary ed-charge" :disabled="!cart.length||busy||!ready||!!storageError" @click="openPayment"><span>Charge {{ money(totals.total,currency) }}</span><Icon name="arrow" /></button><div class="ed-cart-tools"><button class="ed-btn" :disabled="!cart.length||busy||!ready" @click="holdName='';modal='hold'">Hold order</button><button class="ed-btn" :disabled="!cart.length||busy" @click="modal='clear'">Clear</button></div><p class="ed-muted" style="font-size:10px;text-align:center;margin-top:15px">F2 to find a product · F8 to checkout</p></aside></div>
<button v-if="cart.length" class="ed-mobile-cart" @click="viewCart"><span>View order · {{ count }} items</span><strong>{{ money(totals.total,currency) }}</strong><Icon name="arrow" /></button>
<Modal v-if="modal==='variant'" :title="variantProduct.name" @close="modal=''"><p class="ed-muted" style="margin-bottom:20px">Choose an option for this product.</p><div class="ed-form-grid"><button v-for="v in variantProduct.variants" :key="v.id" class="ed-btn ed-variant-choice" :disabled="variantProduct.trackStock&&available(variantProduct,v)-quantityInCart(variantProduct,v)<=0" @click="add(variantProduct,v)"><strong>{{ v.name }}</strong><small style="display:block">{{ money(v.price,currency) }}<span v-if="variantProduct.trackStock"> · {{ Math.max(0,available(variantProduct,v)-quantityInCart(variantProduct,v)) }} available</span></small></button></div></Modal>
<Modal v-if="modal==='payment'" title="Complete the order" :busy="busy" @close="modal=''"><div class="ed-payment-total"><div class="ed-eyebrow">AMOUNT TO COLLECT</div><strong>{{ money(totals.total,currency) }}</strong></div><div class="ed-payment-methods"><button v-for="m in ['Cash','QR Pay','Card']" :key="m" :class="{active:method===m}" :disabled="busy" @click="method=m;confirmed=false;error=''">{{ m }}</button></div><template v-if="method==='Cash'"><label class="ed-field"><span>Cash received ({{ currency }})</span><input v-model="received" type="number" inputmode="decimal" step="0.01" min="0" placeholder="0.00" :disabled="busy"></label><div class="ed-actions" style="margin-top:12px"><button v-for="amount in [totals.total,50,100]" :key="amount" class="ed-btn small" :disabled="busy" @click="received=amount">{{ amount===totals.total?'Exact':money(amount,currency) }}</button></div><div class="ed-summary" style="font-size:15px;margin-top:25px"><span>Change to return</span><strong>{{ money(change,currency) }}</strong></div></template><template v-else><img v-if="method==='QR Pay'&&(company.qrCode||company.qrCodeUrl)" :src="company.qrCode||company.qrCodeUrl" alt="Store payment QR code" style="width:210px;max-height:210px;object-fit:contain;margin:0 auto 20px"><div class="ed-notice"><Icon name="card" /><div><strong>Confirm on your merchant device.</strong>MyFin records the payment. Your merchant app or card terminal confirms it.</div></div><label class="ed-actions" style="font-size:13px"><input v-model="confirmed" type="checkbox" :disabled="busy">Payment confirmed on external device</label></template><section class="ed-editor-section"><h3>Email receipt (optional)</h3><p class="ed-muted">Save the email in your customer directory, then open the receipt in your mail app after payment.</p><div class="ed-form-grid"><label class="ed-field"><span>Customer name</span><input v-model="customerName" :disabled="busy" maxlength="120" autocomplete="name"></label><label class="ed-field"><span>Customer email</span><input v-model.trim="customerEmail" :disabled="busy" type="email" maxlength="254" autocomplete="email" inputmode="email" placeholder="customer@example.com"></label></div></section><div v-if="error" class="ed-alert" role="alert">{{ error }}</div><template #actions><button class="ed-btn" :disabled="busy" @click="modal=''">Back to order</button><button class="ed-btn primary" :disabled="busy" @click="complete"><Icon name="check" />{{ busy?'Saving payment…':'Complete sale' }}</button></template></Modal>
<Modal v-if="modal==='success'" :title="lastSale.syncStatus==='pending'?'Saved on this device':'A good sale.'" @close="modal=''"><div class="ed-success"><div class="ed-success-mark"><Icon name="check" /></div><h3>{{ lastSale.syncStatus==='pending'?'Payment recorded. Sync pending.':'Order complete.' }}</h3><p class="ed-muted" style="font-size:11px;word-break:break-all;margin:10px 0 25px">{{ lastSale.number }}</p><div class="ed-eyebrow">{{ lastSale.change?'CHANGE TO RETURN':'TOTAL COLLECTED' }}</div><strong>{{ money(lastSale.change||lastSale.total,currency) }}</strong></div><div v-if="lastSale.syncStatus==='pending'" class="ed-notice warning"><Icon name="cloud" /><div>Saved safely on this device. Do not take payment again. {{ needsReceiptReview(lastSale.syncError)?'This payment needs manager review. Open Payment reviews to confirm the request; keep this receipt until sync completes.':lastSale.syncError || 'This receipt will sync when your connection returns.' }}</div></div><template #actions><button class="ed-btn" @click="receipt=lastSale;modal=''"><Icon name="printer" />Receipt / Email</button><button class="ed-btn primary" @click="modal=''">New order<Icon name="arrow" /></button></template></Modal>
<Modal v-if="modal==='hold'" title="Keep this order for later." @close="modal=''"><label class="ed-field"><span>Order reference</span><input v-model="holdName" placeholder="Customer name or table" @keydown.enter="hold"></label><template #actions><button class="ed-btn" @click="modal=''">Cancel</button><button class="ed-btn primary" @click="hold">Hold order</button></template></Modal>
<Modal v-if="modal==='held'" title="Held orders" @close="modal=''"><div v-for="(order,i) in held" :key="order.id" class="ed-row"><div><strong>{{ order.name }}</strong><small>{{ order.items.length }} lines · {{ money(order.total,currency) }}</small></div><button class="ed-btn small" @click="restore(i)">Restore</button></div><div v-if="!held.length" class="ed-empty"><Icon name="clock" /><h3>Nothing on hold.</h3><p>Hold an order at checkout to pick it up later.</p></div><p v-else class="ed-muted" style="margin-top:18px;font-size:12px">Restoring an order parks your current cart automatically.</p></Modal>
<Modal v-if="modal==='recent'" title="Recent sales & receipts" wide @close="modal=''"><div v-for="sale in recent" :key="sale.id" class="ed-row"><div><strong style="font-size:11px">{{ sale.number }}</strong><small>{{ sale.customerName||'Walk-in customer' }} · {{ money(sale.total,currency) }}</small><span v-if="sale.syncStatus==='pending'" class="ed-pill warning">Awaiting sync</span></div><button class="ed-btn small" @click="receipt=sale;modal=''"><Icon name="printer" />Receipt</button></div><p v-if="!recent.length" class="ed-muted">Completed sales will appear here.</p></Modal>
<Modal v-if="modal==='clear'" title="Start a fresh order?" @close="modal=''"><p class="ed-muted">Clear the items from this order, or hold it if the customer will return.</p><template #actions><button class="ed-btn" @click="modal=''">Keep order</button><button class="ed-btn danger" @click="cart=[];discount=0;overrideReason='';saleId=newId();customerId='';customerEmail='';customerName='';modal=''">Clear order</button></template></Modal><Receipt v-if="receipt" :sale="receipt" @close="receipt=null" />
</div></template>
